package codex

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Compile-time interface assertions.
var (
	_ agent.HookSupport        = (*CodexAgent)(nil)
	_ agent.HookResponseWriter = (*CodexAgent)(nil)
	_ agent.HookBlockingWriter = (*CodexAgent)(nil)
	_ agent.HookContextWriter  = (*CodexAgent)(nil)
)

// WriteHookResponse outputs a JSON hook response to stdout.
// Codex reads the systemMessage field and displays it to the user.
func (c *CodexAgent) WriteHookResponse(message string) error {
	return c.writeHookResponse(message, "")
}

// WriteBlockingHookResponse outputs a JSON hook response that halts the current turn.
func (c *CodexAgent) WriteBlockingHookResponse(message string) error {
	resp := struct {
		Continue   bool   `json:"continue"`
		StopReason string `json:"stopReason,omitempty"`
	}{
		Continue:   false,
		StopReason: message,
	}
	if err := json.NewEncoder(os.Stdout).Encode(resp); err != nil {
		return fmt.Errorf("failed to encode blocking hook response: %w", err)
	}
	return nil
}

// WriteHookResponseWithContext outputs a JSON hook response that both displays a
// system message and injects additional context into the model.
func (c *CodexAgent) WriteHookResponseWithContext(message, additionalContext string) error {
	return c.writeHookResponse(message, additionalContext)
}

func (c *CodexAgent) writeHookResponse(message, additionalContext string) error {
	type hookSpecificOutput struct {
		AdditionalContext string `json:"additionalContext,omitempty"`
	}

	resp := struct {
		SystemMessage      string              `json:"systemMessage,omitempty"`
		HookSpecificOutput *hookSpecificOutput `json:"hookSpecificOutput,omitempty"`
	}{SystemMessage: message}
	if additionalContext != "" {
		resp.HookSpecificOutput = &hookSpecificOutput{AdditionalContext: additionalContext}
	}
	if err := json.NewEncoder(os.Stdout).Encode(resp); err != nil {
		return fmt.Errorf("failed to encode hook response: %w", err)
	}
	return nil
}

// Codex hook names — these become subcommands under `entire hooks codex`
const (
	HookNameSessionStart     = "session-start"
	HookNameUserPromptSubmit = "user-prompt-submit"
	HookNameStop             = "stop"
	HookNamePreToolUse       = "pre-tool-use"
)

// HookNames returns the hook verbs Codex supports.
func (c *CodexAgent) HookNames() []string {
	return []string{
		HookNameSessionStart,
		HookNameUserPromptSubmit,
		HookNameStop,
		HookNamePreToolUse,
	}
}

// ParseHookEvent translates a Codex hook into a normalized lifecycle Event.
// Returns nil if the hook has no lifecycle significance.
func (c *CodexAgent) ParseHookEvent(_ context.Context, hookName string, stdin io.Reader) (*agent.Event, error) {
	switch hookName {
	case HookNameSessionStart:
		return c.parseSessionStart(stdin)
	case HookNameUserPromptSubmit:
		return c.parseTurnStart(stdin)
	case HookNameStop:
		return c.parseTurnEnd(stdin)
	case HookNamePreToolUse:
		// PreToolUse has no lifecycle significance — pass through
		return nil, nil //nolint:nilnil // nil event = no lifecycle action
	default:
		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
	}
}

func (c *CodexAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionStartRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SessionStart,
		SessionID:  raw.SessionID,
		SessionRef: derefString(raw.TranscriptPath),
		Model:      raw.Model,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CodexAgent) parseTurnStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[userPromptSubmitRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnStart,
		SessionID:  raw.SessionID,
		SessionRef: derefString(raw.TranscriptPath),
		Prompt:     raw.Prompt,
		Timestamp:  time.Now(),
	}, nil
}

func (c *CodexAgent) parseTurnEnd(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[stopRaw](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnEnd,
		SessionID:  raw.SessionID,
		SessionRef: derefString(raw.TranscriptPath),
		Timestamp:  time.Now(),
	}, nil
}

}

// HookBlockingWriter is implemented by agents whose hook response protocol can
// halt the current turn and surface a message to the user. This is used when
// Entire must require explicit confirmation before the agent continues.
type HookBlockingWriter interface {
	Agent

	// WriteBlockingHookResponse outputs a blocking hook response to the user via
	// the agent's hook response protocol.
	WriteBlockingHookResponse(message string) error
}

// HookContextWriter is implemented by agents whose hook response protocol can
// inject additional context directly into the model, separate from any
