53			repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests run outside git repos)
54			if err != nil {
55				return 0, fmt.Errorf("failed to get current directory: %w", err)
56			}
57		}
58	
59		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
60		// Read existing settings if they exist
61		var rawSettings map[string]json.RawMessage
62	
63		// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
64		var rawHooks map[string]json.RawMessage
65	
66		// rawPermissions preserves unknown permission fields (e.g., "ask")
67		var rawPermissions map[string]json.RawMessage
68	
69		existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + settings file name
70		if readErr == nil {
71			if err := json.Unmarshal(existingData, &rawSettings); err != nil {
72				return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
73			}
74			if hooksRaw, ok := rawSettings["hooks"]; ok {
75				if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
76					return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
77				}
78			}
79			if permRaw, ok := rawSettings["permissions"]; ok {
80				if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
81					return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
82				}
83			}
84		} else {
85			rawSettings = make(map[string]json.RawMessage)
86		}
87	
88		if rawHooks == nil {
89			rawHooks = make(map[string]json.RawMessage)
90		}
91		if rawPermissions == nil {
92			rawPermissions = make(map[string]json.RawMessage)
93		}
94	
95		// Parse only the hook types we need to modify
96		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
97		parseHookType(rawHooks, "SessionStart", &sessionStart)
98		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
99		parseHookType(rawHooks, "Stop", &stop)
100		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
101		parseHookType(rawHooks, "PreToolUse", &preToolUse)
102		parseHookType(rawHooks, "PostToolUse", &postToolUse)
103	
104		// If force is true, remove all existing Entire hooks first
105		if force {
106			sessionStart = removeEntireHooks(sessionStart)
107			sessionEnd = removeEntireHooks(sessionEnd)
108			stop = removeEntireHooks(stop)
109			userPromptSubmit = removeEntireHooks(userPromptSubmit)
110			preToolUse = removeEntireHooksFromMatchers(preToolUse)
111			postToolUse = removeEntireHooksFromMatchers(postToolUse)
112		}
113	
114		// Define hook commands
115		var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, postTodoCmd string
116		if localDev {
117			sessionStartCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-start"
118			sessionEndCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-end"
119			stopCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop"
120			userPromptSubmitCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code user-prompt-submit"
121			preTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code pre-task"
122			postTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-task"
123			postTodoCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-todo"
124		} else {
125			sessionStartCmd = "entire hooks claude-code session-start"
126			sessionEndCmd = "entire hooks claude-code session-end"
127			stopCmd = "entire hooks claude-code stop"
128			userPromptSubmitCmd = "entire hooks claude-code user-prompt-submit"
129			preTaskCmd = "entire hooks claude-code pre-task"
130			postTaskCmd = "entire hooks claude-code post-task"
131			postTodoCmd = "entire hooks claude-code post-todo"
132		}
133	
134		count := 0
135	
136		// Add hooks if they don't exist
137		if !hookCommandExists(sessionStart, sessionStartCmd) {
138			sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
139			count++
140		}
141		if !hookCommandExists(sessionEnd, sessionEndCmd) {
142			sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
143			count++
144		}
145		if !hookCommandExists(stop, stopCmd) {
146			stop = addHookToMatcher(stop, "", stopCmd)
147			count++
148		}
149		if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
150			userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
151			count++
152		}
153		if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
154			preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
155			count++
156		}
157		if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
158			postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
159			count++
160		}
161		if !hookCommandExistsWithMatcher(postToolUse, "TodoWrite", postTodoCmd) {
162			postToolUse = addHookToMatcher(postToolUse, "TodoWrite", postTodoCmd)
163			count++
164		}
165	
166		// Add permissions.deny rule if not present
167		permissionsChanged := false
168		var denyRules []string
169		if denyRaw, ok := rawPermissions["deny"]; ok {
170			if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
171				return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
172			}
173		}
174		if !slices.Contains(denyRules, metadataDenyRule) {
175			denyRules = append(denyRules, metadataDenyRule)
176			denyJSON, err := json.Marshal(denyRules)
177			if err != nil {
178				return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
179			}
180			rawPermissions["deny"] = denyJSON
181			permissionsChanged = true
182		}
183	
184		if count == 0 && !permissionsChanged {
185			return 0, nil // All hooks and permissions already installed
186		}
187	
188		// Marshal modified hook types back to rawHooks
189		marshalHookType(rawHooks, "SessionStart", sessionStart)
190		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
191		marshalHookType(rawHooks, "Stop", stop)
192		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
193		marshalHookType(rawHooks, "PreToolUse", preToolUse)
194		marshalHookType(rawHooks, "PostToolUse", postToolUse)
195	
196		// Marshal hooks and update raw settings
197		hooksJSON, err := json.Marshal(rawHooks)
198		if err != nil {
199			return 0, fmt.Errorf("failed to marshal hooks: %w", err)
200		}
201		rawSettings["hooks"] = hooksJSON
202	
203		// Marshal permissions and update raw settings
204		permJSON, err := json.Marshal(rawPermissions)
205		if err != nil {
206			return 0, fmt.Errorf("failed to marshal permissions: %w", err)
207		}
208		rawSettings["permissions"] = permJSON
209	
210		// Write back to file
211		if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
212			return 0, fmt.Errorf("failed to create .claude directory: %w", err)
213		}
214	
215		output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
216		if err != nil {
217			return 0, fmt.Errorf("failed to marshal settings: %w", err)
218		}
219	
220		if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
221			return 0, fmt.Errorf("failed to write settings.json: %w", err)
222		}
223	
224		return count, nil
225	}
226	
227	// parseHookType parses a specific hook type from rawHooks into the target slice.
228	// Silently ignores parse errors (leaves target unchanged).
229	func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]ClaudeHookMatcher) {
230		if data, ok := rawHooks[hookType]; ok {
231			//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
232			json.Unmarshal(data, target)
233		}
234	}
235	
236	// marshalHookType marshals a hook type back to rawHooks.
237	// If the slice is empty, removes the key from rawHooks.
238	func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []ClaudeHookMatcher) {
239		if len(matchers) == 0 {
240			delete(rawHooks, hookType)
241			return
242		}
243		data, err := json.Marshal(matchers)
244		if err != nil {
245			return // Silently ignore marshal errors (shouldn't happen)
246		}
247		rawHooks[hookType] = data
248	}
249	
250	// UninstallHooks removes Entire hooks from Claude Code settings.
251	func (c *ClaudeCodeAgent) UninstallHooks(ctx context.Context) error {
252		// Use repo root to find .claude directory when run from a subdirectory
253		repoRoot, err := paths.WorktreeRoot(ctx)
254		if err != nil {
255			repoRoot = "." // Fallback to CWD if not in a git repo
256		}
257		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
258		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
259		if err != nil {
260			data = nil
261		}
262	
263		var rawSettings map[string]json.RawMessage
264		if len(data) > 0 {
265			if err := json.Unmarshal(data, &rawSettings); err != nil {
266				return fmt.Errorf("failed to parse settings.json: %w", err)
267			}
268		} else {
269			rawSettings = make(map[string]json.RawMessage)
270		}
271	
272		// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
273		var rawHooks map[string]json.RawMessage
274		if hooksRaw, ok := rawSettings["hooks"]; ok {
275			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
276				return fmt.Errorf("failed to parse hooks: %w", err)
277			}
278		}
279		if rawHooks == nil {
280			rawHooks = make(map[string]json.RawMessage)
281		}
282	
283		// Parse only the hook types we need to modify
284		var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
285		parseHookType(rawHooks, "SessionStart", &sessionStart)
286		parseHookType(rawHooks, "SessionEnd", &sessionEnd)
287		parseHookType(rawHooks, "Stop", &stop)
288		parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
289		parseHookType(rawHooks, "PreToolUse", &preToolUse)
290		parseHookType(rawHooks, "PostToolUse", &postToolUse)
291	
292		// Remove Entire hooks from all hook types
293		sessionStart = removeEntireHooks(sessionStart)
294		sessionEnd = removeEntireHooks(sessionEnd)
295		stop = removeEntireHooks(stop)
296		userPromptSubmit = removeEntireHooks(userPromptSubmit)
297		preToolUse = removeEntireHooksFromMatchers(preToolUse)
298		postToolUse = removeEntireHooksFromMatchers(postToolUse)
299	
300		// Marshal modified hook types back to rawHooks
301		marshalHookType(rawHooks, "SessionStart", sessionStart)
302		marshalHookType(rawHooks, "SessionEnd", sessionEnd)
303		marshalHookType(rawHooks, "Stop", stop)
304		marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
305		marshalHookType(rawHooks, "PreToolUse", preToolUse)
306		marshalHookType(rawHooks, "PostToolUse", postToolUse)
307	
308		// Also remove the metadata deny rule from permissions
309		var rawPermissions map[string]json.RawMessage
310		if permRaw, ok := rawSettings["permissions"]; ok {
311			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
312				// If parsing fails, just skip permissions cleanup
313				rawPermissions = nil
314			}
315		}
316	
317		if rawPermissions != nil {
318			if denyRaw, ok := rawPermissions["deny"]; ok {
319				var denyRules []string
320				if err := json.Unmarshal(denyRaw, &denyRules); err == nil {
321					// Filter out the metadata deny rule
322					filteredRules := make([]string, 0, len(denyRules))
323					for _, rule := range denyRules {
324						if rule != metadataDenyRule {
325							filteredRules = append(filteredRules, rule)
326						}
327					}
328					if len(filteredRules) > 0 {
329						denyJSON, err := json.Marshal(filteredRules)
330						if err == nil {
331							rawPermissions["deny"] = denyJSON
332						}
333					} else {
334						// Remove empty deny array
335						delete(rawPermissions, "deny")
336					}
337				}
338			}
339	
340			// If permissions is empty, remove it entirely
341			if len(rawPermissions) > 0 {
342				permJSON, err := json.Marshal(rawPermissions)
343				if err == nil {
344					rawSettings["permissions"] = permJSON
345				}
346			} else {
347				delete(rawSettings, "permissions")
348			}
349		}
350	
351		// Marshal hooks back (preserving unknown hook types)
352		if len(rawHooks) > 0 {
353			hooksJSON, err := json.Marshal(rawHooks)
354			if err != nil {
355				return fmt.Errorf("failed to marshal hooks: %w", err)
356			}
357			rawSettings["hooks"] = hooksJSON
358		} else {
359			delete(rawSettings, "hooks")
360		}
361	
362		if len(data) > 0 {
363			output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
364			if err != nil {
365				return fmt.Errorf("failed to marshal settings: %w", err)
366			}
367			if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
368				return fmt.Errorf("failed to write settings.json: %w", err)
369			}
370		}
371		return nil
372	}
373	
374	// AreHooksInstalled checks if Entire hooks are installed.
375	func (c *ClaudeCodeAgent) AreHooksInstalled(ctx context.Context) bool {
376		// Use repo root to find .claude directory when run from a subdirectory
377		repoRoot, err := paths.WorktreeRoot(ctx)
378		if err != nil {
379			repoRoot = "." // Fallback to CWD if not in a git repo
380		}
381		settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
382		data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
383		if err != nil {
384			return false
385		}
386	
387		var settings ClaudeSettings
388		if err := json.Unmarshal(data, &settings); err != nil {
389			return false
390		}
391	
392		// Check for at least one of our hooks (new or old format)
393		return hookCommandExists(settings.Hooks.Stop, "entire hooks claude-code stop") ||
394			hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop") ||
395			// Backwards compatibility: check for old hook formats
396			hookCommandExists(settings.Hooks.Stop, "entire hooks claudecode stop") ||
397			hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claudecode stop") ||
398			hookCommandExists(settings.Hooks.Stop, "entire rewind claude-hook --stop") ||
399			hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go rewind claude-hook --stop")
400	}
401	
402	// Helper functions for hook management
403	
404	func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
405		for _, matcher := range matchers {
406			for _, hook := range matcher.Hooks {
407				if hook.Command == command {
408					return true
409				}
410			}
411		}
412		return false
413	}
414	
415	func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
416		for _, matcher := range matchers {
417			if matcher.Matcher == matcherName {
418				for _, hook := range matcher.Hooks {
419					if hook.Command == command {
420						return true
421					}
422				}
423			}
424		}
425		return false
426	}
427	
428	func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
429		entry := ClaudeHookEntry{
430			Type:    "command",
431			Command: command,
432		}
433	
434		// If no matcher name, add to a matcher with empty string
435		if matcherName == "" {
436			for i, matcher := range matchers {
437				if matcher.Matcher == "" {
438					matchers[i].Hooks = append(matchers[i].Hooks, entry)
439					return matchers
440				}
441			}
442			return append(matchers, ClaudeHookMatcher{
443				Matcher: "",
444				Hooks:   []ClaudeHookEntry{entry},
445			})
446		}
447	
448		// Find or create matcher with the given name
449		for i, matcher := range matchers {
450			if matcher.Matcher == matcherName {
451				matchers[i].Hooks = append(matchers[i].Hooks, entry)
452				return matchers
453			}
454		}
455	
456		return append(matchers, ClaudeHookMatcher{
457			Matcher: matcherName,
458			Hooks:   []ClaudeHookEntry{entry},
459		})
460	}
461	
462	// isEntireHook checks if a command is an Entire hook (old or new format)
463	func isEntireHook(command string) bool {
464		for _, prefix := range entireHookPrefixes {
465			if strings.HasPrefix(command, prefix) {
466				return true
467			}
468		}
469		return false
470	}
471	
472	// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
473	func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
474		result := make([]ClaudeHookMatcher, 0, len(matchers))
475		for _, matcher := range matchers {
476			filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
477			for _, hook := range matcher.Hooks {
478				if !isEntireHook(hook.Command) {
479					filteredHooks = append(filteredHooks, hook)
480				}
481			}
482			// Only keep the matcher if it has hooks remaining
483			if len(filteredHooks) > 0 {
484				matcher.Hooks = filteredHooks
485				result = append(result, matcher)
486			}
487		}
488		return result
489	}
490	
491	// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
492	// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task", "TodoWrite")
493	func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
494		// Same logic as removeEntireHooks - both work on the same structure
495		return removeEntireHooks(matchers)
496	}
